/* Explains a manual marker. Legacy rules are explicitly separate from verified N26 data. */
(function(){'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</span>`,P=(en,ko)=>`<p>${L(en,ko)}</p>`,edition=x=>String(x||window.MMRuleReference?.currentEdition()||'n26').toLowerCase();
const legacy='https://assets.warhammer-community.com/necromunda_faqs_tradingpost_eng_24.09-cm8tuqawdi.pdf',faq='https://assets.warhammer-community.com/eng_04-09_necromunda_faq_and_errata_september2026-7mwqyegiwp-zrjnipir6m.pdf';
const bindings=new Map();let next=0;
function category(item,options={}){
 if(!item)return {kind:'unknown',base:null};
 if(item.is_custom||item.customAssetId)return {kind:'custom',base:null};
 const all=window.RULES_DATA?.equipment||[];let base=null;
 for(const id of [item.catalogId,item.presetId,item.id].filter(Boolean)){base=all.find(e=>e.id===id);if(base)break;if(id===item.catalogId||id===item.presetId)return {kind:'unknown',base:null};}
 if(!base?.source_verified||options.edition&&edition(base.edition_slug||base.edition)!==edition(options.edition))return {kind:'unknown',base:null};
 const type=String(base.equipment_type||base.equipmentType||'').toLowerCase();return {kind:type==='weapon'?'weapon':type==='wargear'?'wargear':'unknown',base};
}
function control(item,options={}){
 const key=String(++next),ed=edition(options.edition);bindings.set(key,{item:JSON.parse(JSON.stringify(item)),edition:ed});
 return `<div class="mc-control wide"><div class="mc-control-row"><label class="checkline"><input type="checkbox" name="masterCrafted" value="yes" ${item.masterCrafted?'checked':''}>${L('Master-crafted','마스터 크래프티드')}</label><button type="button" class="mc-help-button" data-master-crafted-guide="${key}" aria-haspopup="dialog">${L('Effect, limits & examples','효과·제한·예시')}</button></div><p class="mc-control-note">${L('Manual marker · no automatic price or rules effect','수동 표시 · 비용·효과 자동 적용 없음')}${ed==='n26'?' · '+L('N26 rule unverified','N26 적용 규칙 확인 필요'):''}</p></div>`;
}
function fold(key,en,ko,body){return `<details class="mc-section" data-master-section="${key}"><summary>${L(en,ko)}</summary><div>${body}</div></details>`;}
function markup(item,options={}){
 const ed=edition(options.edition),info=category(item,{edition:ed}),name=item?.name||'',known=info.base,context=known?info.kind==='wargear'?P('This item is Wargear, not a weapon. Ticking the marker does not improve its printed equipment ability.','이 항목은 무기가 아닌 워기어입니다. 체크해도 장비에 적힌 능력이 강화되지 않습니다.'):(info.kind==='weapon'?P('This item is classified as a weapon. That alone does not establish permission to buy or use a Master-crafted version in the selected edition.','이 항목은 무기로 분류됩니다. 그것만으로 현재 판본에서 마스터 크래프티드 구매·사용 조건이 확인되는 것은 아닙니다.'):P('Check this entry’s equipment type and the applicable rule before using the marker.','표시를 사용하기 전에 이 항목의 장비 종류와 적용 규칙을 확인하세요.')):item?P('This entry’s official equipment type is not established here. Check the custom entry and campaign ruling.','이 항목의 공식 장비 종류를 여기서 판정하지 않습니다. 사용자 정의 항목과 캠페인 재정을 확인하세요.') :'';
 const itemLabel=known&&!item?.reference_custom_name&&[known.name,known.name_ko].includes(name)?`<strong>${L(known.name,known.name_ko||window.UKI18n?.name(known.name)||known.name)}</strong>`:`<strong data-user-text>${E(name)}</strong>`;
 const icon=known?.id==='official-001-equipment-corpse-grinder-cult-icon';
 return `<div class="mc-guide" data-master-crafted-help data-master-edition="${E(ed)}"><div class="mc-status">${L('Current control: manual record','현재 옵션: 수동 기록')}${ed==='n26'?P('The verified N26 catalogue has no common Master-crafted trait or purchase rule. The checkbox does not confirm a reroll or a price. The legacy reference below is not a verified N26 benefit.','현재 검증된 N26 목록에는 마스터 크래프티드의 공통 특성·구매 규칙이 없습니다. 체크만으로 재굴림이나 가격을 확정하지 않습니다. 아래 구판 설명은 N26 혜택으로 검증된 내용이 아닙니다.'):P('The reference below is the official 2022 Trading Post, not a complete verification of every later edition. Use the rulebook and campaign pack for your game.','아래 출처는 공식 2022 Trading Post이며, 이후 모든 판본을 검증한 내용은 아닙니다. 실제 게임의 룰북·캠페인 팩을 따르세요.')}</div>${name?`<section class="mc-item">${itemLabel}${context}${icon?P('Example: checking this icon does not add rerolls to Enrage or its Movement bonus.','예: 이 아이콘에 체크해도 인레이지나 이동 보너스에 재굴림이 추가되지 않습니다.'):''}</section>`:''}
 ${fold('purpose','Why use it? · legacy rule','왜 쓰나 · 구판 기준',P('A premium weapon option for rescuing an important missed attack. It adds no action, and does not itself increase Strength, AP or damage.','중요한 공격이 빗나갔을 때 명중 실패를 보완하는 고급 무장 옵션입니다. 행동을 추가하거나 S·AP·데미지 수치를 올리는 효과는 아닙니다.'))}
 ${fold('timing','When and how many times? · legacy rule','언제·몇 번 쓰나 · 구판 기준',P('After that weapon fails a hit roll, its Master-crafted trait allows one failed hit die to be rerolled once per battle. It does not reset each round or activation; it does not reroll wounds, saves or Ammo checks.','그 무기의 명중 굴림이 실패한 뒤, 전투 중 1회 실패한 명중 주사위 1개를 다시 굴릴 수 있습니다. 라운드·활성화마다 회복되지 않으며 운드·세이브·탄약 체크의 재굴림이 아닙니다.')+`<ol class="mc-example"><li>${L('Assume an eligible Master-crafted weapon needs 4+ to hit. A roll of 2 misses.','사용 조건을 충족한 마스터 크래프티드 무기의 명중 목표가 4+라고 가정합니다. 2가 나와 실패했습니다.')}</li><li>${L('Spend its once-per-battle use and reroll that one die. A new 5 hits.','전투 중 1회 사용분을 써서 그 주사위 하나를 다시 굴립니다. 새 결과 5라면 명중입니다.')}</li><li>${L('A new 2 still misses. That weapon has spent the use either way; a later miss cannot use it again this battle.','새 결과가 2면 여전히 실패입니다. 성공·실패와 관계없이 사용분을 썼으므로, 같은 무기는 이번 전투의 다음 실패에 다시 쓰지 못합니다.')}</li></ol>`)}
 ${fold('limits','Who and what qualifies? · legacy rule','사용자·장비 제한 · 구판 기준',P('The 2022 document limits Extravagant Goods to Gang Hierarchy (X), Gang Leaders or Champions. Master-crafted applies to weapons; grenades are Wargear. Armour, an icon or another Wargear item does not become a Master-crafted weapon by ticking a box.','2022 문서의 Extravagant Goods는 Gang Hierarchy (X) 보유자, 갱 리더 또는 챔피언으로 제한됩니다. 마스터 크래프티드는 무기가 대상이며 수류탄은 워기어입니다. 갑옷·아이콘·다른 워기어에 체크한다고 마스터 크래프티드 무기가 되지 않습니다.')+P('Example: an eligible leader purchasing a weapon and a leader carrying a cult icon are different cases. The leader label does not turn the icon into a weapon. These legacy limits do not certify N26 eligibility.','예: 자격 있는 리더가 무기를 구매하는 경우와, 리더가 컬트 아이콘을 드는 경우는 다릅니다. 리더라고 해서 아이콘이 무기가 되지는 않습니다. 이 구판 제한으로 N26 자격을 인증하지 않습니다.'))}
 ${fold('purchase','Price and purchase timing · legacy rule','가격·구입 시점 · 구판 기준',P('Buy a new Master-crafted version for the weapon price plus 25%, rounded up to the next 5 credits. Replacing an owned weapon buys a new version; the original can enter the Stash under this specific exception. It is not simply paying a 25% upgrade fee on the existing item.','무기 가격에 25%를 더한 뒤 5크레딧 단위로 올림해 새 마스터 크래프티드 버전을 구매합니다. 보유 무기를 바꾸는 경우에도 새 버전을 구입하며, 이 예외에 따라 원래 무기를 보관함으로 옮길 수 있습니다. 기존 장비에 25% 차액만 내는 개조가 아닙니다.')+P('Example: a 40-credit weapon becomes 50 credits (40 × 1.25). If replacing one already owned, buy the new weapon for 50, rather than paying only 10. This example is for a weapon, not the 40-credit icon in your record.','예: 40크레딧짜리 무기라면 40 × 1.25 = 50크레딧입니다. 이미 가진 무기를 대체할 때도 새 무기 50크레딧을 구입하는 것이며 10만 내는 것이 아닙니다. 이 예시는 무기용이며, 기록에 있는 40크레딧 아이콘에 적용하는 계산이 아닙니다.'))}
 ${fold('record','What this app actually saves','앱에서 체크하면 무엇이 바뀌나',P('It saves only the Master-crafted marker on this equipment record. Cards or exports may show its label. It does not spend credits, recalculate the cost field, grant legal access, roll a die or track a battle use.','이 장비 기록에 마스터 크래프티드 표시만 저장합니다. 카드·출력물에 표시명이 나타날 수 있습니다. 크레딧 차감·비용칸 재계산·구매 자격 부여·주사위 굴림·전투 중 사용 횟수 관리는 자동 처리하지 않습니다.')+P('Example: entering cost 40 and checking the box saves cost 40. Opening or closing this guide does not change the form. For N26, confirm an applicable rule or agreed campaign ruling before treating the marker as a benefit.','예: 비용 40을 입력하고 체크하면 비용은 40으로 저장됩니다. 이 설명을 열고 닫아도 입력값은 바뀌지 않습니다. N26에서는 적용 규칙이나 합의한 캠페인 재정을 확인한 뒤 표시의 효과를 사용하세요.'))}
 ${fold('sources','Sources and edition scope','출처·판본 확인',`<p><a href="${legacy}#page=21" target="_blank" rel="noopener noreferrer">${L('Official Trading Post (2022), p21: purchase and restrictions','공식 Trading Post (2022), 21쪽: 구매·제한')} ↗</a></p><p><a href="${legacy}#page=26" target="_blank" rel="noopener noreferrer">${L('Same document, p26: Master-crafted trait','같은 문서 26쪽: Master-crafted 특성')} ↗</a></p><p><a href="${faq}" target="_blank" rel="noopener noreferrer">${L('N26 FAQ & Errata, September 2026','N26 FAQ·에라타, 2026년 9월')} ↗</a></p>`+P('The reviewed four-page September 2026 FAQ contains no common Master-crafted rule. That does not prove the rule is absent from every N26 publication. The 2022 text is provided here as a labelled legacy reference only.','확인한 2026년 9월 FAQ 4쪽에는 공통 마스터 크래프티드 규칙이 없습니다. 이것만으로 모든 N26 출판물에서 규칙이 삭제되었다고 단정하지 않습니다. 2022 내용은 구판 참고로만 표시합니다.'))}</div>`;
}
function open(item,options={}){return window.MMRuleReference?.openContext('Master-crafted guide',markup(item,options),{nameKo:'마스터 크래프티드 사용 가이드',activator:options.activator||document.activeElement,nested:!!document.querySelector('.mmrr-overlay')})||false;}
window.addEventListener('click',event=>{const button=event.target.closest?.('[data-master-crafted-guide]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const bound=bindings.get(button.dataset.masterCraftedGuide);if(bound)open(bound.item,{edition:bound.edition,activator:button});},true);
window.MMMasterCrafted={control,markup,open,category};
})();
